style.css:
@-moz-document domain("thomann.de") {
/* Ersetze "Top-Seller" durch "Top Seller!!!!!!" */
    body *:not(script):not(style):not(noscript) {
        font-family: "Arial", sans-serif !important;
    }
    body:before {
        content: "Top Seller!!!!!!";
        display: block;
        visibility: hidden;
        height: 0;
    }
    body *:not(script):not(style):not(noscript):before {
        content: attr(data-original-text);
        visibility: visible;
        height: auto;
    }
    [data-original-text="Top-Seller"] {
        visibility: hidden;
    }
}
